                stat_cell(&r.probes[W_ATT], &cfg),
                stat_cell(&r.probes[M_SPIN], &cfg),
                stat_cell(&r.probes[M_ATT], &cfg),
                fills_cell(r),
            ]
        })
        .collect();
    println!("Spin decomposition (spin = first failed attempt -> reserve success):");
    println!();
    print_table(
        &[
            "placement",
            "flavor",
            "w.spin",
            "w.att",
            "m.spin",
            "m.att",
            "fills/RT",
        ],
        &spin_rows,
    );
}
